const $=id=>document.getElementById(id);let data;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Oslo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'Rolling deadline';const active=j=>j.status==='open'&&(!j.deadline||j.deadline>=today());const days=j=>j.deadline?Math.ceil((new Date(j.deadline+'T23:59:59+02:00')-new Date())/86400000):Infinity;function render(){if(!data)return;const open=data.jobs.filter(active);$('total').textContent=open.length;$('bachelor').textContent=open.filter(j=>j.fit==='potential').length;$('due').textContent=open.filter(j=>days(j)<=7).length;const q=$('search').value.toLocaleLowerCase();let jobs=open.filter(j=>(!q||[j.title,j.company,j.location,j.summary,...j.categories].join(' ').toLocaleLowerCase().includes(q))&&(!$('category').value||j.categories.includes($('category').value))&&(!$('source').value||j.source===$('source').value)&&(!$('location').value||j.location===$('location').value)&&($('stretch').checked||j.fit==='potential'));jobs.sort((a,b)=>$('sort').value==='deadline'?(a.deadline||'9999').localeCompare(b.deadline||'9999'):$('sort').value==='newest'?b.firstSeen.localeCompare(a.firstSeen):(a.fit==='potential'?0:1)-(b.fit==='potential'?0:1)||b.firstSeen.localeCompare(a.firstSeen));$('count').textContent=jobs.length+' roles';$('jobs').innerHTML=jobs.map(j=>`<article class="job ${j.fit==='potential'?'top':''}"><div><div class="company">${esc(j.company)} · ${esc(j.source)}</div><h3>${esc(j.title)}</h3><div class="meta">${esc(j.location)} · ${esc(j.type)}<br>${esc(j.categories.join(' / '))}</div></div><span class="badge ${j.fit==='potential'?'':'stretch'}">${j.fit==='potential'?'Worth exploring':'Extra requirements'}</span><p>${esc(j.summary)}</p><div class="requirement"><strong>Check your fit:</strong> ${esc(j.requirements)}</div><div class="job-bottom"><span>Deadline: ${esc(date(j.deadline))}<br>Checked ${esc(date(j.verifiedAt.slice(0,10)))}</span><a class="apply" target="_blank" rel="noopener noreferrer" href="${esc(j.url)}">View original ↗</a></div></article>`).join('')||'<div class="empty"><strong>No matching open roles.</strong><p>Try broadening your filters. The daily search will check for new opportunities.</p></div>';}async function load(){const button=$('reload');button.disabled=true;button.textContent='Checking…';try{const r=await fetch('/jobs.json',{cache:'no-store'});if(!r.ok)throw Error('Unable to load');const next=await r.json();if(!Array.isArray(next.jobs))throw Error('Invalid collection');data=next;for(const [id,key] of [['location','location'],['source','source']]){const val=$(id).value;$(id).innerHTML=`<option value="">${id==='location'?'All of Norway':'All platforms'}</option>`+[...new Set(data.jobs.map(j=>j[key]))].sort().map(v=>`<option>${esc(v)}</option>`).join('');$(id).value=val;}$('updated').textContent='Last collected '+new Date(data.updatedAt).toLocaleString('en-GB',{timeZone:'Europe/Oslo',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+' Oslo';$('warning').textContent=Date.now()-new Date(data.updatedAt)>36*3600000?'The collection is over 36 hours old. The scheduled refresh may be delayed. Check original adverts for current availability.':'';$('sources').innerHTML=data.sources.map(s=>`<div class="source-row"><div><strong>${esc(s.name)}</strong><small>${esc(s.note)}</small></div><span>${esc(s.status)}</span></div>`).join('');render();}catch(e){$('warning').textContent='Could not load the latest collection. Please try again.';if(!data)$('jobs').innerHTML='<div class="empty">The job collection is temporarily unavailable.</div>';}finally{button.disabled=false;button.textContent='Check for updates ↻';}}for(const id of ['search','category','location','source','stretch','sort'])$(id).addEventListener(id==='search'?'input':'change',render);$('reset').onclick=()=>{for(const id of ['search','category','location','source'])$(id).value='';$('stretch').checked=true;$('sort').value='relevance';render();};$('reload').onclick=load;load();
